209	// loadFile 只读取证地解析地图文件。
210	func loadFile(path string) (*mapState, error) {
211		raw, err := os.ReadFile(path)
212		if err != nil {
213			return nil, err // 含 fs.ErrNotExist，交由调用方/上层用 errors.Is 判断
214		}
215		if len(raw) < headerLen+4 || string(raw[:8]) != fileMagic {
216			return nil, fmt.Errorf("%w: unrecognized header", ErrCorrupt)
217		}
218		version := binary.BigEndian.Uint16(raw[8:10])
219		if version != fileVersion {
220			return nil, fmt.Errorf("%w: version %d", ErrUnsupportedVersion, version)
221		}
222		length := binary.BigEndian.Uint32(raw[10:14])
223		if int(length) != len(raw)-headerLen-4 {
224			return nil, fmt.Errorf("%w: truncated or length mismatch", ErrCorrupt)
225		}
226		want := binary.BigEndian.Uint32(raw[len(raw)-4:])
227		if crc32.ChecksumIEEE(raw[:len(raw)-4]) != want {
228			return nil, fmt.Errorf("%w: checksum mismatch", ErrCorrupt)
229		}
230	
231		var fd fileData
232		if err := json.Unmarshal(raw[headerLen:headerLen+int(length)], &fd); err != nil {
233			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
234		}
235		if err := validateLoaded(&fd); err != nil {
236			return nil, err
237		}
238	
239		st := &mapState{
240			config:       fd.Config,
241			trajectory:   fd.Trajectory,
242			landmarks:    make(map[string]*landmarkState, len(fd.Landmarks)),
243			segments:     make(map[string]*segmentRecord, len(fd.Segments)),
244			sources:      make([]*frameSource, len(fd.Trajectory)-1),
245			corrections:  make([]*CorrectionRecord, 0, len(fd.Corrections)),
246			corrIndex:    make(map[string]string, len(fd.Corrections)),
247			invalRecords: make([]*invalidationRecord, 0, len(fd.Invalidations)),
248			invalIndex:   make(map[string]*invalidationRecord, len(fd.Invalidations)),
249		}
250		// 旧文件不携带逐帧依据：有帧而 sources 缺省即旧地图。无帧时二者
251		// 无法区分也无需区分（尚无范围可校正）。
252		oldFormat := len(fd.Sources) == 0 && len(fd.Trajectory) > 1
253		for _, lmj := range fd.Landmarks {
254			lm := &landmarkState{}
255			if len(lmj.Occurrences) > 0 {
256				// 新格式：历次出现按编号递增保存。
257				for _, oj := range lmj.Occurrences {
258					lm.appearances = append(lm.appearances, &occurrenceState{
259						x:             oj.X,
260						y:             oj.Y,
261						count:         oj.Count,
262						legacyCount:   oj.LegacyCount,
263						legacyMX:      oj.LegacyMX,
264						legacyMY:      oj.LegacyMY,
265						firstSeenTime: oj.FirstSeenTime,
266						hasFirstSeen:  oj.HasFirstSeen,
267						active:        oj.Active,
268						invalidTime:   oj.InvalidTime,
269						invalidReason: oj.InvalidReason,
270						invalidOpID:   oj.InvalidOpID,
271					})
272				}
273			} else {
274				// 兼容旧布局：一个平铺路标即第 1 次有效出现。
275				occ := &occurrenceState{
276					x:      lmj.X,
277					y:      lmj.Y,
278					count:  lmj.Count,
279					active: true,
280				}
281				if oldFormat {
282					// 旧文件中该路标的全部既有观测都是固定旧贡献，位置取
283					// 文件中的聚合值；缺少逐帧来源，首次观测时间未知。
284					occ.legacyCount = lmj.Count
285					occ.legacyMX, occ.legacyMY = lmj.X, lmj.Y
286					occ.hasFirstSeen = false
287				} else {
288					occ.legacyCount = lmj.LegacyCount
289					occ.legacyMX, occ.legacyMY = lmj.LegacyMX, lmj.LegacyMY
290					// 含固定旧贡献时最早观测缺少来源，首次观测时间未知；
291					// 否则从逐帧依据中恢复该出现第一次被观测到的帧时间。
292					occ.hasFirstSeen = lmj.LegacyCount == 0
293					if occ.hasFirstSeen {
294						for k, src := range fd.Sources {
295							if src == nil {
296								continue
297							}
298							found := false
299							for _, ob := range src.Observations {
300								if ob.ID == lmj.ID {
301									found = true
302									break
303								}
304							}
305							if found {
306								occ.firstSeenTime = fd.Trajectory[k+1].Time
307								break
308							}
309						}
310					}
311				}
312				lm.appearances = append(lm.appearances, occ)
313			}
314			st.landmarks[lmj.ID] = lm
315		}
316		for _, sg := range fd.Segments {
317			ids := sg.Result.LandmarkIDs
318			if ids == nil {
319				ids = []string{}
320			}
321			st.segments[sg.ID] = &segmentRecord{
322				hash:   sg.Hash,
323				result: ImportResult{EndPose: sg.Result.EndPose, LandmarkIDs: ids},
324			}
325		}
326		if !oldFormat {
327			for k, src := range fd.Sources {
328				if src == nil {
329					continue // 来自旧文件的帧：保持依据缺失
330				}
331				obs := append([]Observation(nil), src.Observations...)
332				st.sources[k] = &frameSource{moveVariance: src.MoveVariance, observations: obs}
333			}
334		}
335		for _, cj := range fd.Corrections {
336			rec := &CorrectionRecord{
337				ID:        cj.ID,
338				Anchor:    cj.Anchor,
339				Target:    cj.Target,
340				EndTime:   cj.EndTime,
341				Poses:     make([]PoseChange, len(cj.Poses)),
342				Landmarks: make([]LandmarkChange, len(cj.Landmarks)),
343			}
344			for i, pc := range cj.Poses {
345				rec.Poses[i] = PoseChange{Before: pc.Before, After: pc.After}
346			}
347			for i, lc := range cj.Landmarks {
348				occNum := lc.Occurrence
349				if occNum == 0 {
350					occNum = 1 // 更早版本写出的校正记录不带编号，只有第 1 次出现
351				}
352				rec.Landmarks[i] = LandmarkChange{ID: lc.ID, Occurrence: occNum, Before: lc.Before, After: lc.After}
353			}
354			st.corrections = append(st.corrections, rec)
355			st.corrIndex[cj.ID] = canonicalCorrectionHash(cj.Anchor, cj.Target)
356		}
357		for _, ij := range fd.Invalidations {
358			lms := make([]InvalidatedLandmark, len(ij.Landmarks))
359			for i, l := range ij.Landmarks {
360				lms[i] = InvalidatedLandmark{ID: l.ID, Occurrence: l.Occurrence}
361			}
362			rec := &invalidationRecord{
363				id:     ij.ID,
364				reason: ij.Reason,
365				hash:   ij.Hash,
366				result: InvalidationResult{Time: ij.Time, Landmarks: lms},
367			}
368			st.invalRecords = append(st.invalRecords, rec)
369			st.invalIndex[ij.ID] = rec
370		}
371		return st, nil
372	}
