8	
9	// 回环校正中观测转换到地图坐标后溢出：校正目标、原始观测与校正后的机器人
10	// 位姿都只有有限数值，但路标地图坐标仍可能因数值过大产生无穷值。必须按
11	// non_finite 拒绝并指出异常观测所在帧的实际时间、路标标识与从 1 起的出现
12	// 编号，而不是误报为距离冲突，也不能只给锚点时间。
13	func TestCorrectionNonFiniteObservation(t *testing.T) {
14		hugeCfg := Config{
15			InitialTime: 0, InitialX: 0, InitialY: 0, InitialHeading: 0,
16			InitialVariance: 0, MaxInterval: 1000, MergeDistance: 10,
17		}
18	
19		// 任务示例：原点、朝向零，t=50/100/200 保存三个无运动帧，t=50 与
20		// t=200 观测 L(1e308,0)；以 t=100 为锚点把目标位置改为 (1e308,0)。
21		// 机器人位置仍有限，但 t=200 的路标地图坐标溢出。
22		t.Run("overflow is not a distance conflict", func(t *testing.T) {
23			path := filepath.Join(t.TempDir(), "map.bin")
24			m, err := Create(path, hugeCfg)
25			if err != nil {
26				t.Fatalf("Create: %v", err)
