28			defer m.Close()
29			if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
30				{Time: 50, Observations: []Observation{{ID: "L", X: 1e308}}},
31				{Time: 100},
32				{Time: 200, Observations: []Observation{{ID: "L", X: 1e308}}},
33			}}); err != nil {
34				t.Fatal(err)
35			}
36			before, err := os.ReadFile(path)
37			if err != nil {
38				t.Fatal(err)
39			}
40	
41			_, err = m.Correct(Correction{ID: "c", Anchor: 100, Target: CorrectionTarget{X: 1e308, Y: 0}})
42			r, ok := AsRejectError(err)
