58	
59			// 整次校正不生效：位姿、路标、观测次数、校正记录与本地文件保持原样。
60			cur, _ := m.CurrentPose()
61			if cur.Time != 200 || cur.X != 0 || cur.Y != 0 {
62				t.Fatalf("pose changed after rejection: %+v", cur)
63			}
64			p, _ := m.PoseAt(100)
65			if p.X != 0 || p.Y != 0 {
